insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('addx','ADDX','en_radar',(select slug from categorias where nombre='Acciones y capital privado'),(select slug from regiones where nombre='Asia-Pacífico'),'Marketplace','Acreditado','Alto','Varias','https://addx.co','Licencia de mercado reconocido del MAS de Singapur. Accionistas de su matriz: la bolsa SGX, Heliconia (del grupo Temasek), UOB y otros.','Fondos de capital riesgo y private equity troceados para inversores acreditados.','2026-07-26');
insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('archax','Archax','en_radar',(select slug from categorias where nombre='Acciones y capital privado'),(select slug from regiones where nombre='Reino Unido'),'Marketplace','Institucional','Alto','Varias','https://archax.com','Autorizada y supervisada por la FCA británica con el número 838656, como exchange, bróker y custodio, e inscrita en su registro de criptoactivos. Tiene permiso para operar un sistema multilateral de negociación, no solo para intermediar.','Mercado regulado de valores digitales en Londres que reúne emisión, negociación y custodia bajo la misma licencia. Cuidado con los clones: la FCA tiene avisos publicados sobre webs que la suplantan, y el dominio válido es archax.com.','2026-08-08');
insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('artex-global-markets','ARTEX Global Markets','en_radar',(select slug from categorias where nombre='Materias primas'),(select slug from regiones where nombre='Liechtenstein'),'Marketplace','Acreditado','Alto','No usa blockchain','https://www.artexgm.com','Licencia de sistema multilateral de negociación (MTF) bajo MiFID II del regulador de Liechtenstein; SIX aporta compensación y liquidación.','Mercado regulado de acciones sobre obras de arte: cada cuadro se trocea en acciones de 100 €. Ojo: el token «ARTEX» de BNB Chain no tiene relación con esta plataforma.','2026-07-26');
insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('backed-finance','Backed Finance','en_radar',(select slug from categorias where nombre='Acciones y capital privado'),(select slug from regiones where nombre='Suiza'),'Emisor','Minorista','Bajo','Ethereum, Base, Gnosis','https://backed.fi','Grupo suizo; los xStocks los emite una sociedad de Jersey (Backed Assets (JE) Limited), con el activo 1:1 en custodios regulados y prueba de reservas pública.','Réplicas tokenizadas de acciones y bonos cotizados.','2026-07-26');
insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('blocksquare','Blocksquare','en_radar',(select slug from categorias where nombre='Inmobiliario'),(select slug from regiones where nombre='Unión Europea'),'Infraestructura','Empresas','No aplica','Ethereum','https://blocksquare.io','Cada token se apoya en un acuerdo societario del emisor, guardado en IPFS, que identifica el inmueble con sus datos registrales y le obliga frente a los tenedores. No es una inscripción en el registro de la propiedad.','Tecnología para que una inmobiliaria tokenice sus propios activos.','2026-07-26');
insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('centrifuge','Centrifuge','en_radar',(select slug from categorias where nombre='Crédito privado'),(select slug from regiones where nombre='Global'),'Infraestructura','Institucional','Alto','Ethereum, Base','https://centrifuge.io','Es un protocolo, no el emisor: cada fondo tiene su propio vehículo, jurisdicción y documento de oferta. Sus términos dicen que los productos pueden no estar regulados.','Financiación de carteras de préstamos y facturas con garantía fuera de cadena.','2026-07-26');
insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('courtyard','Courtyard','en_radar',(select slug from categorias where nombre='Materias primas'),(select slug from regiones where nombre='EE. UU.'),'Marketplace','Minorista','Bajo','Polygon','https://courtyard.io','Es un mercado de NFT de coleccionables físicos, no un mercado de valores con licencia. No hemos podido comprobar hoy en su web la custodia ni el canje.','Cromos y coleccionables físicos (cartas Pokémon, deportivas) tokenizados.','2026-07-26');
insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('figure','Figure','en_radar',(select slug from categorias where nombre='Crédito privado'),(select slug from regiones where nombre='EE. UU.'),'Emisor','Institucional','Alto','Provenance','https://figure.com','Figure Securities, Inc. es bróker-dealer registrado ante la SEC (FINRA, CRD 307093) y opera un ATS. Ese registro no cubre a las demás sociedades de Figure.','Mercado de capitales nativo en blockchain para crédito privado y activos tokenizados, con préstamos hipotecarios (HELOC) en su propia cadena.','2026-07-26');
