insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('franklin-templeton','Franklin Templeton','en_radar',(select slug from categorias where nombre='Tesoro y fondos'),(select slug from regiones where nombre='EE. UU.'),'Emisor','Minorista','Bajo','Stellar, Varias','https://franklintempleton.com','Fondo monetario estadounidense (FOBXX). Solo para residentes en EE. UU.: su folleto del 01/08/2026 dice que no está registrado ni puede ofrecerse en ningún país de la UE o del EEE.','Fondo monetario de deuda pública con el registro de partícipes llevado en cadena desde 2021.','2026-07-26');
