insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('lofty','Lofty','en_radar',(select slug from categorias where nombre='Inmobiliario'),(select slug from regiones where nombre='EE. UU.'),'Marketplace','Minorista','Bajo','Algorand','https://lofty.ai','Según sus términos, Lofty no está registrada ante la SEC ni ante ningún otro organismo, y no es un bróker-dealer registrado. Su mercado no es una oferta registrada.','Vivienda unifamiliar troceada desde 50 $, con reparto de renta diario y voto de los inversores en cada propiedad.','2026-07-26');
insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('maple-finance','Maple Finance','en_radar',(select slug from categorias where nombre='Crédito privado'),(select slug from regiones where nombre='Global'),'Emisor','Institucional','Alto','Ethereum, Solana','https://maple.finance','Su crédito institucional es para inversores acreditados que completan el alta (KYC/AML); syrupUSDC y syrupUSDT están abiertos a cualquiera en cadena fuera de EE. UU. Los términos de esa interfaz dicen que la operadora no está registrada ante ningún regulador.','Crédito privado para instituciones y productos de rendimiento en cadena (syrupUSDC y syrupUSDT).','2026-07-26');
insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('midas','Midas','en_radar',(select slug from categorias where nombre='Tesoro y fondos'),(select slug from regiones where nombre='Unión Europea'),'Emisor','Minorista','Medio','Ethereum','https://midas.app','Emite bajo un folleto base aprobado por la FMA de Liechtenstein el 17/07/2026 y notificado a la CNMV. Aprobar el folleto no es una licencia: según el propio folleto, el emisor no está regulado por la FMA.','Certificados tokenizados sobre estrategias de renta fija.','2026-07-26');
insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('ondo-finance','Ondo Finance','en_radar',(select slug from categorias where nombre='Tesoro y fondos'),(select slug from regiones where nombre='EE. UU.'),'Emisor','Acreditado','Alto','Ethereum, Solana','https://ondo.finance','En el EEE, USDY exige ser cliente profesional o inversor cualificado. Emisor, producto y jurisdicción se revisan por separado: no hay una licencia única para toda la marca.','Exposición a deuda pública de EE. UU. y, desde 2026, a ETFs de Franklin Templeton tokenizados.','2026-07-26');
