insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('reental','Reental','en_radar',(select slug from categorias where nombre='Inmobiliario'),(select slug from regiones where nombre='España'),'Emisor','Minorista','Bajo','Varias','https://reental.co','Según su web, es una empresa norteamericana que ofrece inversiones desde EE. UU. y España, y su actividad no está sujeta a autorización ni registro previo de la CNMV: no hay un supervisor que la vigile.','Proyectos inmobiliarios en España y Latinoamérica desde 100 €.','2026-07-26');
insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('republic','Republic','en_radar',(select slug from categorias where nombre='Acciones y capital privado'),(select slug from regiones where nombre='EE. UU.'),'Marketplace','Minorista','Bajo','Varias','https://republic.com','Opera con entidades registradas y supervisadas en EE. UU.: OpenDeal Portal LLC como portal de financiación ante la SEC y FINRA desde 2016, y OpenDeal Broker LLC como bróker-dealer miembro de FINRA y SIPC.','Mercados privados troceados desde importes pequeños: empresas sin cotizar, fondos, cine, deporte y arte. Importante: sus Mirror Tokens no son acciones de la empresa que replican, sino pagarés de la propia Republic que pagan solo si llega una salida a bolsa o una compra.','2026-08-08');
