insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('spiko','Spiko','en_radar',(select slug from categorias where nombre='Tesoro y fondos'),(select slug from regiones where nombre='Unión Europea'),'Emisor','Minorista','Bajo','Varias','https://spiko.io','Fondos monetarios de la SICAV francesa Spiko SICAV, gestionados por Twenty First Capital. No todos aparecen hoy en la base pública de la AMF: compruébalo fondo a fondo.','Fondos en euros y dólares para la tesorería de empresas y particulares, con reembolso diario.','2026-07-26');
