insert into plataformas (slug,nombre,estado,categoria_slug,region_slug,actor,acceso,ticket,cadenas,web,aval,nota,verificada_el) values ('swarm','Swarm','en_radar',(select slug from categorias where nombre='Acciones y capital privado'),(select slug from regiones where nombre='Liechtenstein'),'Marketplace','Minorista','Bajo','Polygon','https://swarm.com','La contraparte es Swarm Capital GmbH (Vaduz, Liechtenstein). No consta licencia: BaFin no la tiene en su base de datos (20/11/2026) y su aviso legal no nombra supervisor.','Acciones y bonos tokenizados. Se contrata con una sociedad de Liechtenstein; sus términos eligen la ley alemana.','2026-07-26');
