insert into plataformas (slug,nombre,estado,etiqueta_descarte,motivo_descarte,verificada_el) values ('realt','RealT','descartada','Liquidación anunciada','En julio de 2025, Detroit demandó a RealT, a sus dos cofundadores y a 165 sociedades vinculadas por más de 400 inmuebles residenciales que, según la demanda, incumplían las normas de construcción, salud y seguridad. Ese mismo mes, una orden judicial provisional le prohibió cobrar alquileres en sus inmuebles hasta que tuvieran certificado de cumplimiento y le ordenó hacer reparaciones. En julio de 2026, su cofundador Jean-Marc Jacobson dijo a los inversores que la empresa entraba en liquidación voluntaria y que iban a vender todos sus activos. RealT había vendido en tokens participaciones de unos 700 inmuebles de Detroit.','2026-08-06');
insert into fuentes (plataforma_id,url,titulo,publicada_el,consultada_el) values ((select id from plataformas where slug='realt'),'https://detroitmi.gov/news/city-scores-major-win-tenants-living-troubled-real-token-properties-are-subject-sweeping-lawsuit','Ciudad de Detroit · la ciudad gana una medida para los inquilinos de Real Token',null,'2026-08-06');
insert into fuentes (plataforma_id,url,titulo,publicada_el,consultada_el) values ((select id from plataformas where slug='realt'),'https://www.bridgedetroit.com/detroit-sues-blockchain-real-estate-firm/','BridgeDetroit · Detroit demanda a Real Token por cientos de infracciones',null,'2026-08-06');
