insert into fuentes (plataforma_id,url,titulo,publicada_el,consultada_el) values ((select id from plataformas where slug='realt'),'https://outliermedia.org/realt-crypto-real-estate-detroit-properties/','Outlier Media · RealT planea vender sus inmuebles de Detroit','2026-07-16','2026-11-04');
insert into plataformas (slug,nombre,estado,etiqueta_descarte,motivo_descarte,verificada_el) values ('toucan-protocol','Toucan Protocol','descartada','Registro bloqueado en 2022','En mayo de 2022, Verra prohibió tokenizar créditos ya retirados y el American Carbon Registry prohibió tokenizar los suyos sin su autorización expresa. Hoy Toucan solo tokeniza créditos del registro Puro (su fondo CHAR, de biocarbón), con los créditos inmovilizados en ese registro. No la hemos vuelto a evaluar para el radar.','2026-08-06');
